# ------------------- Base de datos (SQLite local o PostgreSQL en servidor) -------------------
def _pg_cfg():
    try:
        paths = [os.path.join(".streamlit", "secrets.toml"),
                 os.path.join(os.path.expanduser("~"), ".streamlit", "secrets.toml")]
        if not any(os.path.exists(p) for p in paths):
            return None
        if "postgres" in st.secrets:
            return dict(st.secrets["postgres"])
    except Exception:
        pass
    return None

def _sb_cfg():
    try:
        if "supabase" in st.secrets:
            return dict(st.secrets["supabase"])
    except Exception:
        pass
    return None

# Valores por defecto (SQLite). Se recalculan tras set_page_config (más abajo).
PGCFG = None
PG = False
PH = "?"
PK = "INTEGER PRIMARY KEY AUTOINCREMENT"

def _new_pg():
    import psycopg2
    return psycopg2.connect(
        host=PGCFG.get("host", "localhost"), port=int(PGCFG.get("port", 5432)),
        dbname=PGCFG["dbname"], user=PGCFG["user"], password=PGCFG["password"],
        sslmode="require", connect_timeout=10,
        keepalives=1, keepalives_idle=30, keepalives_interval=10, keepalives_count=5)

@st.cache_resource
def _pg_box():
    box = {"c": None}
    box["c"] = _new_pg(); box["c"].autocommit = True
    return box

def _reset_pg():
    box = _pg_box()
    try: box["c"].close()
    except Exception: pass
    box["c"] = _new_pg(); box["c"].autocommit = True

def conn():
    if not PG:
        return sqlite3.connect(DB)
    box = _pg_box()
    try:
        cur = box["c"].cursor(); cur.execute("SELECT 1"); cur.fetchone(); cur.close()
    except Exception:
        _reset_pg()
    return box["c"]

def run(sql, params=(), fetch=None):
    for intento in (1, 2):
        c = conn(); cur = c.cursor()
        try:
            cur.execute(sql, params)
            out = cur.fetchone() if fetch == "one" else (cur.fetchall() if fetch == "all" else None)
            if not PG: c.commit()
            cur.close()
            if not PG: c.close()
            return out
        except Exception:
            try: cur.close()
            except Exception: pass
            if PG and intento == 1:
                _reset_pg(); continue
            if not PG:
                try: c.close()
                except Exception: pass
            raise

def _add_col(tabla, col, tipo="TEXT"):
    c = conn(); cur = c.cursor()
    try:
        if PG:
            cur.execute("SELECT column_name FROM information_schema.columns WHERE table_name=%s", (tabla,))
            ex = [r[0] for r in cur.fetchall()]
        else:
            cur.execute(f"PRAGMA table_info({tabla})")
            ex = [r[1] for r in cur.fetchall()]
        if col not in ex:
            cur.execute(f"ALTER TABLE {tabla} ADD COLUMN {col} {tipo}")
            if not PG: c.commit()
    finally:
        cur.close()
        if not PG: c.close()

def init_db():
    run(f"""CREATE TABLE IF NOT EXISTS usuarios(
        id {PK}, username TEXT UNIQUE, nombre TEXT, salt TEXT, pw_hash TEXT, rol TEXT,
        cedula TEXT, celular TEXT, licencia_cat TEXT, licencia_vence TEXT, examen_vence TEXT, placa TEXT)""")
    run(f"""CREATE TABLE IF NOT EXISTS vehiculos(
        id {PK}, placa TEXT, trailer TEXT, marca TEXT, modelo TEXT, propietario TEXT,
        soat_vence TEXT, tecnomec_vence TEXT, poliza_vence TEXT)""")
    run(f"""CREATE TABLE IF NOT EXISTS clientes(
        id {PK}, nombre TEXT, nit TEXT, contacto TEXT, telefono TEXT, email TEXT, direccion TEXT, ciudad TEXT)""")
    run(f"""CREATE TABLE IF NOT EXISTS chequeos(
        id {PK}, fecha TEXT, tipo TEXT, conductor TEXT, vehiculo TEXT, resultado TEXT,
        detalle TEXT, observaciones TEXT, owner TEXT)""")
    run(f"""CREATE TABLE IF NOT EXISTS documentos(
        id {PK}, fecha TEXT, categoria TEXT, relacionado TEXT, descripcion TEXT,
        archivo TEXT, ruta TEXT, owner TEXT)""")
    for col in ["cedula", "celular", "licencia_cat", "licencia_vence", "examen_vence", "placa"]:
        _add_col("usuarios", col)
    _add_col("chequeos", "owner"); _add_col("documentos", "owner")

def insertar(tabla, datos):
    cols = ",".join(datos); ph = ",".join([PH] * len(datos))
    run(f"INSERT INTO {tabla}({cols}) VALUES({ph})", list(datos.values()))

def borrar(tabla, rid):
    run(f"DELETE FROM {tabla} WHERE id={PH}", (int(rid),))

def leer(tabla, orden="id DESC"):
    c = conn()
    df = pd.read_sql_query(f"SELECT * FROM {tabla} ORDER BY {orden}", c)
    if not PG:
        c.close()
    return df

def conductores_df():
    u = leer("usuarios")
    return u[u["rol"] == "conductor"].copy() if not u.empty else u

# ------------------- Autenticación -------------------
def hash_pw(pw, salt=None):
    salt = salt or secrets.token_hex(16)
    return salt, hashlib.sha256((salt + pw).encode("utf-8")).hexdigest()

def crear_usuario(username, nombre, pw, rol, cedula="", celular="",
                  licencia_cat="", licencia_vence="", examen_vence="", placa=""):
    salt, h = hash_pw(pw)
    insertar("usuarios", dict(username=username.strip().lower(), nombre=U(nombre), salt=salt,
             pw_hash=h, rol=rol, cedula=U(cedula), celular=U(celular), licencia_cat=U(licencia_cat),
             licencia_vence=licencia_vence, examen_vence=examen_vence, placa=U(placa)))

def verificar_login(username, pw):
    row = run(f"SELECT username, nombre, salt, pw_hash, rol, placa FROM usuarios WHERE username={PH}",
              (username.strip().lower(),), fetch="one")
    if not row: return None
    uname, nombre, salt, pw_hash, rol, placa = row
    if hash_pw(pw, salt)[1] == pw_hash:
        return {"username": uname, "nombre": nombre, "rol": rol, "placa": placa or ""}
    return None

def seed():
    if leer("usuarios").empty:
        if leer("vehiculos").empty:
            insertar("vehiculos", dict(placa="ABC123", trailer="R-100", marca="KENWORTH",
                     modelo="2019", propietario="RUBEN CONTRERAS", soat_vence="2026-09-30",
                     tecnomec_vence="2026-08-15", poliza_vence="2026-12-31"))
        crear_usuario("oficina", "OFICINA", "oficina123", "oficina")
        crear_usuario("conductor1", "CONDUCTOR UNO", "cond123", "conductor", cedula="16000000",
                      celular="3200000000", licencia_cat="C3", licencia_vence="2026-07-20",
                      examen_vence="2026-10-10", placa="ABC123")

# ------------------- Utilidades -------------------
def dias_para(fecha_str):
    if not fecha_str: return None
    try: return (datetime.strptime(fecha_str, "%Y-%m-%d").date() - date.today()).days
    except: return None

def estado_vencimiento(fecha_str):
    d = dias_para(fecha_str)
    if d is None: return "Sin fecha", "gray"
    if d < 0:     return f"Vencido hace {abs(d)} días", ROJO
    if d <= 30:   return f"Vence en {d} días", "#E08A1E"
    return f"Vigente ({d} días)", VERDE_OSC

def opciones(df, col):
    return df[col].tolist() if not df.empty else []

def meta_enriquecida(row):
    u = leer("usuarios"); v = leer("vehiculos")
    ur = u[u["username"] == row.get("owner")] if not u.empty else u
    vr = v[v["placa"] == row.get("vehiculo")] if not v.empty else v
    g = lambda df, col: (df.iloc[0][col] if not df.empty else "")
    return dict(fecha=row["fecha"], conductor=row["conductor"], cedula=g(ur, "cedula"),
                celular=g(ur, "celular"), vehiculo=row["vehiculo"], trailer=g(vr, "trailer"),
                marca=g(vr, "marca"), modelo=g(vr, "modelo"), propietario=g(vr, "propietario"),
                resultado=row["resultado"], observaciones=row.get("observaciones", ""))

# ------------------- Word detallado -------------------
def generar_word_chequeo(meta, detalle):
    from docx import Document
    from docx.shared import Inches, Pt, RGBColor
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    def shade(cell, color):
        tcPr = cell._tc.get_or_add_tcPr()
        sh = OxmlElement('w:shd'); sh.set(qn('w:val'), 'clear'); sh.set(qn('w:fill'), color)
        tcPr.append(sh)

    def fmt(cell, white=False, size=None, center=False):
        for p in cell.paragraphs:
            if center: p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            for r in p.runs:
                r.bold = True
                if white: r.font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
                if size: r.font.size = Pt(size)

    doc = Document()
    for s in doc.sections:
        s.left_margin = s.right_margin = Inches(0.55)
        s.top_margin = s.bottom_margin = Inches(0.5)

    head = doc.add_table(rows=1, cols=2); head.style = "Table Grid"
    try:
        head.cell(0, 0).paragraphs[0].add_run().add_picture(
            io.BytesIO(base64.b64decode(LOGO_B64)), width=Inches(2.3))
        head.cell(0, 0).paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    except Exception:
        pass
    rc = head.cell(0, 1)
    p = rc.paragraphs[0]; p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run("CHEQUEO PREOPERACIONAL DE VEHÍCULO")
    r.bold = True; r.font.size = Pt(13); r.font.color.rgb = RGBColor(0x1E, 0x7A, 0x2E)
    for txt in ["Código: FT-FLOTA-01", "Versión: 01",
                "ENERPETROL · Soluciones en transporte y combustible"]:
        pp = rc.add_paragraph(txt); pp.alignment = WD_ALIGN_PARAGRAPH.CENTER

    doc.add_paragraph("")
    info = doc.add_table(rows=4, cols=4); info.style = "Table Grid"
    datos = [
        ("CONDUCTOR", meta.get("conductor", ""), "CÉDULA", meta.get("cedula", "")),
        ("CELULAR", meta.get("celular", ""), "FECHA", meta.get("fecha", "")),
        ("PLACA", meta.get("vehiculo", ""), "TRÁILER / RMO", meta.get("trailer", "")),
        ("MARCA / MODELO", f"{meta.get('marca','')} {meta.get('modelo','')}".strip(),
         "PROPIETARIO", meta.get("propietario", "")),
    ]
    for i, (k1, v1, k2, v2) in enumerate(datos):
        info.cell(i, 0).text = k1; info.cell(i, 1).text = str(v1)
        info.cell(i, 2).text = k2; info.cell(i, 3).text = str(v2)
        for col in (0, 2):
            shade(info.cell(i, col), "D9EAD3"); fmt(info.cell(i, col))

    res = doc.add_table(rows=1, cols=2); res.style = "Table Grid"
    res.cell(0, 0).text = "RESULTADO"; res.cell(0, 1).text = meta.get("resultado", "")
    shade(res.cell(0, 0), "1E7A2E"); fmt(res.cell(0, 0), white=True)
    no_apto = meta.get("resultado") == "NO APTO"
    shade(res.cell(0, 1), "C0392B" if no_apto else "D9EAD3"); fmt(res.cell(0, 1), white=no_apto)

    doc.add_paragraph("")
    sec = doc.add_paragraph(); rr = sec.add_run("PUNTOS DE INSPECCIÓN PREOPERACIONAL")
    rr.bold = True; rr.font.color.rgb = RGBColor(0x1E, 0x7A, 0x2E)

    it = doc.add_table(rows=1, cols=6); it.style = "Table Grid"
    headers = ["No.", "ÍTEM", "CUMPLE", "NO CUMPLE", "N/A", "OBSERVACIONES"]
    widths = [Inches(0.45), Inches(2.9), Inches(0.75), Inches(0.85), Inches(0.5), Inches(1.65)]
    for i, htext in enumerate(headers):
        cel = it.rows[0].cells[i]; cel.text = htext; cel.width = widths[i]
        shade(cel, "1E7A2E"); fmt(cel, white=True, size=9, center=True)
    n = 1
    for item, estado in detalle.items():
        cells = it.add_row().cells
        cells[0].text = str(n); cells[1].text = item.upper()
        mark = {"Cumple": 2, "No cumple": 3, "N/A": 4}.get(estado, 4)
        cells[mark].text = "X"; fmt(cells[mark], center=True)
        if estado == "No cumple":
            cells[5].text = "REQUIERE ATENCIÓN"
        for i, wd in enumerate(widths):
            cells[i].width = wd
        n += 1

    doc.add_paragraph("")
    obs = doc.add_paragraph(); obs.add_run("OBSERVACIONES GENERALES: ").bold = True
    obs.add_run(meta.get("observaciones") or "—")

    doc.add_paragraph("")
    ap = doc.add_table(rows=2, cols=3); ap.style = "Table Grid"
    for i, t in enumerate(["CONDUCTOR", "REVISADO POR (OPERACIONES)", "HSE / SEGURIDAD"]):
        ap.cell(0, i).text = t; shade(ap.cell(0, i), "D9EAD3"); fmt(ap.cell(0, i), center=True)
        ap.cell(1, i).text = "\n\nFirma: ____________________"

    foot = doc.add_paragraph()
    fr = foot.add_run("Este documento certifica la inspección preoperacional del vehículo "
                      "antes de iniciar la operación.")
    fr.italic = True; fr.font.size = Pt(8)

    out = io.BytesIO(); doc.save(out); return out.getvalue()

def boton_word(row, key):
    meta = meta_enriquecida(row)
    try:
        detalle = json.loads(row["detalle"]) if row["detalle"] else {}
    except Exception:
        detalle = {}
    data = generar_word_chequeo(meta, detalle)
    st.download_button("Word", data, file_name=f"CHEQUEO_{row['fecha']}_{row['vehiculo']}.docx",
                       mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                       key=key)

