def storage_subir(ruta, data, content_type="application/octet-stream"):
    import requests
    r = requests.post(f"{SB_URL}/storage/v1/object/{SB_BUCKET}/{ruta}",
                      headers={"Authorization": f"Bearer {SB_KEY}", "apikey": SB_KEY,
                               "Content-Type": content_type, "x-upsert": "true"},
                      data=bytes(data), timeout=30)
    if not r.ok:
        raise RuntimeError(f"Storage error {r.status_code}: {r.text}")

def storage_descargar(ruta):
    import requests
    r = requests.get(f"{SB_URL}/storage/v1/object/{SB_BUCKET}/{ruta}",
                     headers={"Authorization": f"Bearer {SB_KEY}", "apikey": SB_KEY}, timeout=30)
    if not r.ok:
        raise RuntimeError(f"Storage error {r.status_code}: {r.text}")
    return r.content

def descargar_doc(d, key, label="Descargar"):
    try:
        if SB:
            data = storage_descargar(d["ruta"])
        else:
            with open(d["ruta"], "rb") as f:
                data = f.read()
        st.download_button(label, data, file_name=d["archivo"], key=key)
    except Exception:
        st.write("archivo no disponible")

