def ficha_conductor(u):
    st.markdown(f"#### {u['nombre']}  ·  CC {u['cedula'] or '—'}  ·  CEL {u['celular'] or '—'}")
    cols = st.columns(3)
    txt, color = estado_vencimiento(u["licencia_vence"])
    cols[0].markdown(f"**LICENCIA {u['licencia_cat'] or ''}**<br><span style='color:{color}'>{txt}</span>", unsafe_allow_html=True)
    txt, color = estado_vencimiento(u["examen_vence"])
    cols[1].markdown(f"**EXAMEN MÉDICO**<br><span style='color:{color}'>{txt}</span>", unsafe_allow_html=True)
    cols[2].markdown(f"**VEHÍCULO ASIGNADO**<br>{u['placa'] or '—'}", unsafe_allow_html=True)
    veh = vehiculos[vehiculos["placa"] == u["placa"]] if u["placa"] else pd.DataFrame()
    if not veh.empty:
        v = veh.iloc[0]; vc = st.columns(3)
        for col, (campo, etq) in zip(vc, [("soat_vence", "SOAT VEHÍCULO"),
                                          ("tecnomec_vence", "TECNOMECÁNICA"), ("poliza_vence", "PÓLIZA")]):
            t2, c2 = estado_vencimiento(v[campo])
            col.markdown(f"**{etq}**<br><span style='color:{c2}'>{t2}</span>", unsafe_allow_html=True)
    chq = leer("chequeos"); chq = chq[chq["owner"] == u["username"]] if not chq.empty else chq
    st.markdown("**CHEQUEOS**")
    if chq.empty:
        st.caption("Sin chequeos.")
    else:
        for _, r in chq.head(8).iterrows():
            cc = st.columns([2, 2, 2, 1.2])
            cc[0].write(r["fecha"]); cc[1].write(r["vehiculo"]); cc[2].write(r["resultado"])
            with cc[3]:
                boton_word(r, key=f"fw_{u['username']}_{r['id']}")
    docs = leer("documentos"); docs = docs[docs["owner"] == u["username"]] if not docs.empty else docs
    st.markdown("**DOCUMENTOS**")
    if docs.empty:
        st.caption("Sin documentos.")
    else:
        for _, d in docs.iterrows():
            cc = st.columns([3, 3, 1.2])
            cc[0].write(f"{d['categoria']} · {d['fecha']}"); cc[1].write(d["archivo"])
            with cc[2]:
                descargar_doc(d, key=f"fd_{d['id']}")

# ============ BUSCAR ============
if menu == "Buscar":
    st.header("Buscar conductor o vehículo")
    q = st.text_input("Escribe nombre, cédula o placa", key="buscar_q").strip().lower()
    if not q:
        st.info("Escribe algo para buscar. Ej.: un nombre, una cédula o una placa.")
    else:
        enc = conductores[conductores.apply(
            lambda r: q in str(r["nombre"]).lower() or q in str(r["cedula"]).lower()
            or q in str(r["placa"]).lower(), axis=1)] if not conductores.empty else conductores
        if not enc.empty:
            st.subheader("Conductores")
            for _, u in enc.iterrows():
                with st.expander(f"{u['nombre']}  —  {u['placa'] or 'SIN VEHÍCULO'}"):
                    ficha_conductor(u)
        vm = vehiculos[vehiculos["placa"].str.lower().str.contains(q, na=False)] if not vehiculos.empty else vehiculos
        if not vm.empty:
            st.subheader("Vehículos")
            for _, v in vm.iterrows():
                with st.expander(f"{v['placa']}  —  {v['marca']} {v['modelo']}"):
                    vc = st.columns(3)
                    for col, (campo, etq) in zip(vc, [("soat_vence", "SOAT"),
                                                      ("tecnomec_vence", "TECNOMECÁNICA"), ("poliza_vence", "PÓLIZA")]):
                        t2, c2 = estado_vencimiento(v[campo])
                        col.markdown(f"**{etq}**<br><span style='color:{c2}'>{t2}</span>", unsafe_allow_html=True)
                    asg = conductores[conductores["placa"] == v["placa"]] if not conductores.empty else pd.DataFrame()
                    st.markdown(f"**CONDUCTOR ASIGNADO:** {asg.iloc[0]['nombre'] if not asg.empty else '—'}")
        if enc.empty and vm.empty:
            st.warning("Sin resultados para esa búsqueda.")

# ============ TABLERO ============
elif menu == "Tablero y alertas":
    st.header("Tablero y alertas de vencimientos")
    alertas = []
    for _, v in vehiculos.iterrows():
        for campo, etq in [("soat_vence", "SOAT"), ("tecnomec_vence", "TECNOMECÁNICA"), ("poliza_vence", "PÓLIZA")]:
            d = dias_para(v[campo])
            if d is not None and d <= 30:
                alertas.append({"Tipo": f"VEHÍCULO {v['placa']}", "Documento": etq, "Vence": v[campo], "Días": d})
    for _, u in conductores.iterrows():
        for campo, etq in [("licencia_vence", "LICENCIA"), ("examen_vence", "EXAMEN MÉDICO")]:
            d = dias_para(u[campo])
            if d is not None and d <= 30:
                alertas.append({"Tipo": f"CONDUCTOR {u['nombre']}", "Documento": etq, "Vence": u[campo], "Días": d})
    m1, m2, m3 = st.columns(3)
    m1.metric("Vehículos", len(vehiculos)); m2.metric("Conductores", len(conductores)); m3.metric("Alertas", len(alertas))
    st.subheader("Documentos vencidos o por vencer (≤ 30 días)")
    if alertas:
        st.dataframe(pd.DataFrame(alertas).sort_values("Días"), use_container_width=True, hide_index=True)
    else:
        st.success("Sin vencimientos próximos. Todo al día.")

# ============ VEHÍCULOS ============
elif menu == "Vehículos":
    st.header("Vehículos")
    with st.expander("Registrar vehículo", expanded=vehiculos.empty):
        a, b, c = st.columns(3)
        placa = a.text_input("Placa", key="veh_placa"); trailer = b.text_input("Trailer / RMO", key="veh_trailer")
        marca = c.text_input("Marca", key="veh_marca"); modelo = a.text_input("Modelo / año", key="veh_modelo")
        propietario = b.text_input("Propietario", key="veh_prop")
        d1, d2, d3 = st.columns(3)
        soat = d1.date_input("SOAT vence", value=date.today(), key="veh_soat")
        tecno = d2.date_input("Tecnomecánica vence", value=date.today(), key="veh_tecno")
        pol = d3.date_input("Póliza vence", value=date.today(), key="veh_pol")
        if st.button("Guardar vehículo", type="primary", key="veh_save"):
            if placa.strip():
                insertar("vehiculos", dict(placa=U(placa), trailer=U(trailer), marca=U(marca),
                         modelo=U(modelo), propietario=U(propietario), soat_vence=str(soat),
                         tecnomec_vence=str(tecno), poliza_vence=str(pol)))
                st.success("Vehículo guardado."); st.rerun()
            else:
                st.warning("La placa es obligatoria.")
    for _, v in vehiculos.iterrows():
        st.markdown(f"### {v['placa']}  ·  {v['marca']} {v['modelo']}")
        cols = st.columns(4)
        for col, (campo, etq) in zip(cols, [("soat_vence", "SOAT"), ("tecnomec_vence", "TECNOMECÁNICA"),
                                            ("poliza_vence", "PÓLIZA"), ("", "")]):
            if campo:
                txt, color = estado_vencimiento(v[campo])
                col.markdown(f"**{etq}**<br><span style='color:{color}'>{txt}</span>", unsafe_allow_html=True)
        cols[3].button("Eliminar", key=f"delveh_{v['id']}", on_click=borrar, args=("vehiculos", v["id"]))
        st.divider()

# ============ CONDUCTORES ============
elif menu == "Conductores":
    st.header("Conductores")
    st.caption("Cada conductor tiene su cuenta y su vehículo asignado. Con esto inician sesión.")
    with st.expander("Registrar conductor", expanded=conductores.empty):
        a, b, c = st.columns(3)
        nombre = a.text_input("Nombre completo", key="con_nom")
        cedula = b.text_input("Cédula", key="con_ced")
        celular = c.text_input("Celular", key="con_cel")
        cat = a.text_input("Categoría licencia (ej. C3)", key="con_cat")
        placa_sel = b.selectbox("Vehículo asignado", ["—"] + opciones(vehiculos, "placa"), key="con_placa")
        d1, d2 = st.columns(2)
        lic = d1.date_input("Licencia vence", value=date.today(), key="con_lic")
        exa = d2.date_input("Examen médico vence", value=date.today(), key="con_exa")
        st.markdown("**Datos de acceso**")
        e1, e2 = st.columns(2)
        usuario = e1.text_input("Usuario (sin espacios)", key="con_user")
        clave = e2.text_input("Contraseña", type="password", key="con_pw")
        if st.button("Guardar conductor", type="primary", key="con_save"):
            if nombre.strip() and usuario.strip() and clave.strip():
                u_all = leer("usuarios")
                if not u_all[u_all["username"] == usuario.strip().lower()].empty:
                    st.warning("Ese usuario ya existe.")
                else:
                    crear_usuario(usuario, nombre, clave, "conductor", cedula=cedula, celular=celular,
                                  licencia_cat=cat, licencia_vence=str(lic), examen_vence=str(exa),
                                  placa="" if placa_sel == "—" else placa_sel)
                    st.success("Conductor creado."); st.rerun()
            else:
                st.warning("Nombre, usuario y contraseña son obligatorios.")
    for _, u in conductores.iterrows():
        c1, c2 = st.columns([5, 1])
        with c1:
            ficha_conductor(u)
        c2.button("Eliminar", key=f"delcon_{u['id']}", on_click=borrar, args=("usuarios", u["id"]))
        st.divider()

